var results=new List<object>();var failures=new List<string>();
void Check(bool value){if(!value)throw new Exception("assertion failed");}
void Reject<T>(Action a,string? fragment=null) where T:Exception{try{a();}catch(T e){if(fragment is null||e.Message.Contains(fragment,StringComparison.Ordinal))return;throw;}throw new Exception("expected "+typeof(T).Name);}
void Reset(){EffectApi.Stop();ContentApi.Stop();ContentApi.Start();EffectApi.Start();NativeHookGroup.Allow=true;NativeHookGroup.Lost=false;GameSession.Identity=new(0,"test",1);ModuleEffectHelper.moduleEffects=new();MelonLoader.MelonLogger.Errors.Clear();}
void Case(string name,Action action){try{Reset();action();results.Add(new{name,passed=true});}catch(Exception e){failures.Add(name+": "+e);results.Add(new{name,passed=false,error=e.Message});}}
MachineBatchContext Batch(int n=3)=>new(new GameItem(),new[]{new MachineItemTake(new GameItem(),5){Value=100m}},new Dictionary<string,GameItem>(),n);
Effect NewEffect(string id)=>new(){identifier=id};
NativeApplicationView View(string id)=>EffectApi.Snapshot().Single(x=>x.ContentId==id);
void Register(string id="sample.fixed",bool random=false,Func<Effect>? factory=null){Check(EffectApi.RegisterEffect("sample",id,factory??(()=>NewEffect(id)),random).Accepted);}
object? Prefix(){var args=new object?[]{null};try{typeof(EffectApi).GetMethod("RandomPrefix",BindingFlags.NonPublic|BindingFlags.Static)!.Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException!;}return args[0];}
Exception? Final(object? state,Exception? error=null)=>(Exception?)typeof(EffectApi).GetMethod("RandomFinalizer",BindingFlags.NonPublic|BindingFlags.Static)!.Invoke(null,new[]{error,state});
